mutations.find:
let out = this.generic(s);
for (const p of this.fullName) out = out.replace(p, CONTACT);
return out;

mutations.replace:
let out = this.savedPhone ? s.replace(this.savedPhone, PHONE) : s;
out = out.replace(PHONE_LIKE, PHONE);
for (const p of this.fullName) out = out.replace(p, CONTACT);
return out.replace(EMAIL_LIKE, EMAIL);
